using System; 
using System.Collections.Generic;
using System.Linq;
using Comindware.Data.Entity;
using Comindware.TeamNetwork.Api.Data.UserCommands;
using Comindware.TeamNetwork.Api.Data;

class Script
{
    public static UserCommandResult Main(UserCommandContext userCommandContext, Comindware.Entities entities)
    { 
        var navigationId = "";
        try
        {
            var id = userCommandContext.ObjectIds[0];
            var statusPlanned_Data = Api.TeamNetwork.ObjectService.Get("InspectionPointStatuses_calc", new Dictionary<string,object>{{"Code_calc","planned"}},null, new[]{"id"});
            var status = statusPlanned_Data["id"].ToString();
            var statusStarted_Data = Api.TeamNetwork.ObjectService.Get("InspectionStatuses_calc", new Dictionary<string,object>{{"Code_calc","started"}},null, new[]{"id"});
            var statusObchod = statusStarted_Data["id"].ToString();
            var user = userCommandContext.CurrentUserId;
            var pokazateliTree_List = new List<PokazateliTree>();
            var pokazateli_Data = Api.TeamNetwork.ObjectService.GetPropertyValues(new []{id}, new []{"Readings_calc"});
            if((pokazateli_Data[id].TryGetValue("Readings_calc", out object pokazateli_obj)) && pokazateli_obj != null)
            {
                var pokazateli_Array = pokazateli_Data[id]["Readings_calc"] as object[];
                foreach(var pokazatel_Element in pokazateli_Array)
                {
                    var pokazatel = pokazatel_Element.ToString();
                    var pomeschenie_Data = Api.TeamNetwork.ObjectService.GetPropertyValues(new []{pokazatel}, new[]{"Space_calc"});
                    if((pomeschenie_Data[pokazatel].TryGetValue("Space_calc", out object pomeschenie_obj)) && pomeschenie_obj!= null)
                    {
                        var pomeschenie = pomeschenie_obj.ToString();
                        var pokazateliTree = pokazateliTree_List.Find(x => x.Pomesheniye == pomeschenie);
                        if(pokazateliTree != null)
                        {
                            var pokazatelNew_DAta = new Dictionary<string,object>
                            {
                                {"KPI_calc",pokazatel},
                                //{"Oborudovanie", oborudovanie},
                                {"Space_calc", pomeschenie},
                                {"Route1_calc", id}
                            };
                            var pokazatelNew = Api.TeamNetwork.ObjectService.CreateWithAlias("KPIRecords_calc", pokazatelNew_DAta);
                            pokazateliTree.Pokazateli.Add(pokazatelNew);
                        }
                        else
                        {
                            var pokazatelNew_DAta = new Dictionary<string,object>
                            {
                                {"KPI_calc",pokazatel},
                                //{"Oborudovanie", oborudovanie},
                                {"Space_calc", pomeschenie},
                                {"Route1_calc", id}
                            };
                            var pokazatelNew = Api.TeamNetwork.ObjectService.CreateWithAlias("KPIRecords_calc", pokazatelNew_DAta);
                            pokazateliTree_List.Add(new PokazateliTree(pomeschenie,new List<string>{pokazatelNew}));
                        }
                    }
                }
                var obchodList = new List<string>();
                foreach(var pokazateliTree_Element in pokazateliTree_List)
                {
                    var data = new Dictionary<string,object>
                    {
                        {"Space_calc", pokazateliTree_Element.Pomesheniye},
                        {"Route1_calc", id},
                        {"Status_calc", status},
                        {"AssignedAssignee_calc", user},
                        {"KPIRecords_calc", pokazateliTree_Element.Pokazateli}
                    };
                    obchodList.Add(Api.TeamNetwork.ObjectService.CreateWithAlias("InspectionPoints_calc",data));

                }

                DateTime saveNow = DateTime.Now;
                var dataObkhod = new Dictionary<string,object>
                {
                    {"AssignedAssignee_calc", user},
                    {"Route_calc", id},
                    {"ActualStartDateTime_calc", /*DateTime.Now.AddHours(10)*/ DateTime.UtcNow},
                    {"Status_calc",statusObchod},
                    {"InspectionPoints_calc", obchodList}
                };
              var obchod = Api.TeamNetwork.ObjectService.CreateWithAlias("Inspections_calc", dataObkhod);
                navigationId = obchod;
            }
        }
        catch
        {
            var resulterror = new UserCommandResult
            {
                Success = false,
                Commited = true,
                ResultType = UserCommandResultType.Notificate,
                Messages = new[]
                {
                    new UserCommandMessage
                    {
                        Severity = SeverityLevel.Normal,
                        Text = "Failed"
                        }
                }         
            };
            return resulterror;
        }

        var result = new UserCommandResult
        {
            Success = true,
            Commited = true,
            ResultType = UserCommandResultType.Navigate,
            NavigationResult = new UserCommandNavigationResult//в результате выполнения скрипта происходит смена навигации
            {
                ContainerId = "oa.223",//Id шаблон записи
                Context = ContextType.Record,//отображение записи шз
                ObjectId = navigationId//Id записи в шз
                },
            Messages = new[]
            {
                new UserCommandMessage
                {
                    Severity = SeverityLevel.Normal,
                    Text = "Success"
                    }
            }
        };
        return result;
    }
}

public class PokazateliTree
{
    public string Pomesheniye {get;set;}
    public List<string> Pokazateli {get;set;}

    public PokazateliTree()
    {}

    public PokazateliTree( string pomesheniye, List<string> pokazateli)
    {
        Pomesheniye = pomesheniye; Pokazateli = pokazateli;
    }
}
